public class Manacher {
    public String longestPalindrome(String s) {
        if (s.isEmpty()) return "";
        StringBuilder sb = new StringBuilder("#");
        for (char c : s.toCharArray()) { sb.append(c).append('#'); }
        String t = sb.toString();
        int m = t.length();
        int[] p = new int[m];
        int center = 0, right = 0;
        int bestLen = 0, bestCenter = 0;
        for (int i = 0; i < m; i++) {
            if (i < right) {
                int mirror = 2 * center - i;
                p[i] = Math.min(right - i, p[mirror]);
            }
            while (i - p[i] - 1 >= 0 && i + p[i] + 1 < m
                    && t.charAt(i - p[i] - 1) == t.charAt(i + p[i] + 1)) {
                p[i]++;
            }
            if (i + p[i] > right) { center = i; right = i + p[i]; }
            if (p[i] > bestLen) { bestLen = p[i]; bestCenter = i; }
        }
        int start = (bestCenter - bestLen) / 2;
        return s.substring(start, start + bestLen);
    }

    public static void main(String[] args) {
        System.out.println(new Manacher().longestPalindrome("abba"));
        System.out.println(new Manacher().longestPalindrome("babad"));
    }
}
